// 品牌贴纸：新的品牌加到地图上；英文名字和介绍给英文界面
BRANDS.forEach(b=>{
  if (!b.old && !STICKERS.some(s=>s[0] === b.n)) STICKERS.push([b.n, b.e, b.lon, b.lat, 3, "B", b.r, b.d]);
  if (window.MAP_EN){ MAP_EN.names[b.n] = MAP_EN.names[b.n] || b.en; if (b.d_en) MAP_EN.desc[b.n] = b.d_en; }
});
// 品牌里卖的东西：用通用名字（运动鞋、手机……），放进和菜单一样的格子里（照片、名字、点一下听一句怎么问）
// 每件商品带一个亚马逊英国站的搜索链接（联盟 ID heyvoyo-21），在那里看现在在卖的样子
const amzUrl = q => BRAND_PRODUCTS.amazon_site + "/s?k=" + encodeURIComponent(q) + "&tag=" + BRAND_PRODUCTS.amazon_tag;
Object.entries(BRAND_PRODUCTS.brands).forEach(([n, B])=>{ MENUS[n] = B.products.map(k=>Object.assign({}, BRAND_PRODUCTS.items[k], {amz: amzUrl(B.amazon[k])})); });

